package com.dixitdada.journalApp.controller; import com.dixitdada.journalApp.entity.User; import com.dixitdada.journalApp.service.UserService; import lombok.RequiredArgsConstructor; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/user") @RequiredArgsConstructor public class UserController { private final UserService users; @GetMapping public User me(Authentication a){return users.get(a.getName());} @DeleteMapping public void delete(Authentication a){users.delete(a.getName());} }